class ItemSource(private val api: ItemApi, private val query: String) : PagingSource<String, Item>() {
  override suspend fun load(params: LoadParams<String>): LoadResult<String, Item> {
    val page = api.items(query = query, size = params.loadSize, cursor = params.key)
    return LoadResult.Page(
      data = page.items,
      prevKey = page.prevCursor,     // null at the start
      nextKey = page.nextCursor,     // null at the end of the collection
    )
  }
  override fun getRefreshKey(state: PagingState<String, Item>) =
      state.anchorPosition?.let { state.closestItemToPosition(it)?.id }
}

fun items(query: String): Flow<Item> = flow {
  var cursor: String? = null
  do {
    val page = api.list(query = query, cursor = cursor, size = 100)
    emitAll(page.items.asFlow())
    cursor = page.nextPageToken
  } while (cursor != null)
}

